<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import UiDialog from '@/components/ui/UiDialog.vue'
import { onboardingDemo as demo, type JoinRequest } from '@/lib/onboarding-demo'
const props = defineProps<{ screen: string; rooms: { name: string; residents: number; capacity: number; state: string; pending?: boolean }[] }>()
const emit = defineEmits<{ go: [screen: string]; receive: [name: string] }>()
const name = ref(''), phone = ref(''), username = ref(''), password = ref(''), repeat = ref(''), agreed = ref(false)
const propertyName = ref(''), address = ref(''), contact = ref(''), contactPhone = ref('')
const code = ref(''), matched = ref(false), error = ref(''), message = ref('')
const requestFilter = ref('pending'), selected = ref<JoinRequest>(), action = ref<'approve' | 'reject' | 'receive' | ''>(''), reason = ref(''), roomName = ref('')
const mine = computed(() => demo.requests.find(r => r.mine))
const pending = computed(() => demo.requests.filter(r => r.status === 'pending').length)
const requests = computed(() => demo.requests.filter(r => !requestFilter.value || r.status === requestFilter.value))
const statusText = (status: string) => ({ pending: 'Chờ duyệt', approved: 'Đã duyệt', rejected: 'Đã từ chối', withdrawn: 'Đã rút' })[status] ?? status
const isPhone = (value: string) => /^0\d{9}$/.test(value.replace(/\s/g, ''))
function register() {
  error.value = ''
  if (!name.value.trim() || !/^[a-zA-Z0-9_]{3,30}$/.test(username.value) || !isPhone(phone.value)) { error.value = 'Điền họ tên, số điện thoại 10 số và tên đăng nhập từ 3–30 ký tự không dấu.'; return }
  if (password.value.length < 8) { error.value = 'Mật khẩu cần ít nhất 8 ký tự.'; return }
  if (password.value !== repeat.value) { error.value = 'Hai mật khẩu chưa khớp.'; return }
  if (!agreed.value) { error.value = 'Xác nhận bạn đang dùng thông tin mẫu để tiếp tục.'; return }
  demo.registered = true; demo.name = name.value.trim(); demo.phone = phone.value.trim(); password.value = ''; repeat.value = ''; const next = demo.afterRegister; demo.afterRegister = 'start'; emit('go', next)
}
function createProperty() {
  error.value = ''
  if (!propertyName.value.trim() || !address.value.trim() || !contact.value.trim() || !isPhone(contactPhone.value)) { error.value = 'Điền tên khu, địa chỉ, người liên hệ và số điện thoại hợp lệ.'; return }
  demo.property = { name: propertyName.value.trim(), address: address.value.trim(), contact: contact.value.trim(), phone: contactPhone.value.trim() }; demo.created = true; demo.invite = 'RENT26AB'; demo.inviteActive = true; emit('go', 'invite')
}
function checkCode() {
  error.value = ''; matched.value = false
  if (!demo.inviteActive || code.value.trim().toUpperCase() !== demo.invite) { error.value = 'Mã không đúng hoặc đã bị thu hồi. Kiểm tra lại với chủ trọ.'; return }
  matched.value = true
}
function submitJoin() {
  if (!demo.inviteActive || code.value.trim().toUpperCase() !== demo.invite) { matched.value = false; error.value = 'Mã đã thay đổi. Hãy kiểm tra lại.'; return }
  if (mine.value && ['pending', 'approved'].includes(mine.value.status)) { emit('go', 'status'); return }
  if (mine.value) { mine.value.status = 'pending'; mine.value.reason = '' }
  else demo.requests.push({ id: Date.now(), name: demo.name, phone: demo.phone, status: 'pending', reason: '', mine: true })
  emit('go', 'status')
}
function decide(request: JoinRequest, kind: typeof action.value) { selected.value = request; action.value = kind; reason.value = ''; roomName.value = ''; error.value = '' }
function confirm() {
  if (!selected.value) return
  if (action.value === 'reject' && !reason.value.trim()) { error.value = 'Nhập lý do để người gửi biết cần làm gì tiếp theo.'; return }
  if (action.value === 'receive') {
    const room = props.rooms.find(r => r.name === roomName.value && r.state === 'Còn trống' && !r.pending)
    if (!room) { error.value = 'Chọn một phòng còn trống.'; return }
    selected.value.room = room.name; emit('receive', room.name)
  } else { selected.value.status = action.value === 'approve' ? 'approved' : 'rejected'; selected.value.reason = reason.value.trim() }
  message.value = 'Đã cập nhật trong bản mẫu. Chuyển sang Trạng thái người thuê để xem kết quả.'; action.value = ''
}
async function copyCode() { try { await navigator.clipboard.writeText(demo.invite); message.value = 'Đã sao chép mã mẫu.' } catch { message.value = 'Bạn có thể chọn và sao chép mã hiển thị bên dưới.' } }
const month = ref('2026-11')
const monthly = computed(() => month.value === '2026-11' ? { entered: 2, left: 1, people: 3, vacant: 3, income: 5600000, expense: 650000, total: 8400000 } : { entered: 3, left: 0, people: 2, vacant: 4, income: 2800000, expense: 350000, total: 5600000 })
const money = (value: number) => new Intl.NumberFormat('vi-VN').format(value) + ' đ'
const totalPeople = computed(() => props.rooms.reduce((sum, r) => sum + r.residents, 0))
watch(() => props.screen, () => { error.value = ''; message.value = ''; action.value = ''; matched.value = false })
</script>

<template>
  <div class="extra">
    <p v-if="message" class="feedback" role="status">{{ message }}</p>
    <template v-if="screen === 'register'">
      <div class="entry-layout"><section class="entry-intro"><p class="eyebrow">CHÀO MỪNG ĐẾN RENTBASE</p><h1>Một tài khoản.<br />Một nơi để an tâm.</h1><p>Tìm căn phòng phù hợp, kết nối với chủ trọ và theo dõi việc thuê trong cùng một không gian.</p><ol class="intro-list"><li><b>01</b><span>Tạo tài khoản cá nhân</span></li><li><b>02</b><span>Tìm phòng hoặc nhập mã khu trọ</span></li><li><b>03</b><span>Chờ chủ trọ xác nhận để tham gia</span></li></ol><p class="fine">Bạn là chủ trọ? Sau đăng ký, chọn “Tạo khu trọ” để bắt đầu quản lý.</p></section>
      <section class="card"><p class="eyebrow">BẮT ĐẦU TẠI ĐÂY</p><h2>Tạo tài khoản</h2><p class="sub">Bản thử giao diện — không tạo tài khoản thật.</p><form @submit.prevent="register" novalidate><label>Họ và tên<input v-model="name" autocomplete="off" maxlength="100" placeholder="Nguyễn Minh An" /></label><div class="form-grid"><label>Số điện thoại<input v-model="phone" type="tel" autocomplete="off" placeholder="0900000000" maxlength="15" /></label><label>Tên đăng nhập<input v-model="username" autocomplete="off" placeholder="minhan" maxlength="30" /></label></div><div class="form-grid"><label>Mật khẩu mẫu<input v-model="password" type="password" autocomplete="new-password" placeholder="Tối thiểu 8 ký tự" /></label><label>Nhập lại mật khẩu<input v-model="repeat" type="password" autocomplete="new-password" /></label></div><label class="checkbox"><input v-model="agreed" type="checkbox" /><span>Tôi đang thử bằng thông tin mẫu, không dùng mật khẩu thật.</span></label><p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary full" type="submit">Tạo tài khoản mẫu →</button></form></section></div>
    </template>

    <template v-else-if="screen === 'start'">
      <div class="heading centered"><p class="eyebrow">BƯỚC TIẾP THEO CỦA BẠN</p><h1>Chào {{ demo.name }}.</h1><p>Chọn đúng nhu cầu. Bạn có thể đổi lựa chọn sau.</p></div><div class="choices"><button class="choice" @click="emit('go', 'find')"><span class="choice-symbol">01</span><h2>Tôi đang tìm phòng</h2><p>Xem phòng trống, chi phí và đặt lịch đến xem.</p><strong>Tìm phòng phù hợp →</strong></button><button class="choice" @click="emit('go', 'join')"><span class="choice-symbol">02</span><h2>Tôi có mã khu trọ</h2><p>Nhập mã chủ trọ gửi và chờ duyệt tham gia.</p><strong>Nhập mã khu trọ →</strong></button><button class="choice" @click="emit('go', 'create')"><span class="choice-symbol">03</span><h2>Tôi quản lý nhà trọ</h2><p>Tạo khu trọ của bạn, thêm phòng và mời người thuê.</p><strong>Tạo khu trọ →</strong></button></div><p class="footnote">Tạo khu trọ chỉ cấp quyền quản lý khu của bạn. Nhập mã không cấp quyền quản trị.</p>
    </template>

    <template v-else-if="screen === 'create'">
      <div class="heading"><p class="eyebrow">KHÔNG GIAN QUẢN LÝ RIÊNG</p><h1>Tạo khu trọ của bạn</h1><p>Thiết lập thông tin cơ bản trước. Bạn có thể bổ sung ảnh và phòng sau.</p></div><div class="two-columns"><section class="card"><form @submit.prevent="createProperty" novalidate><label>Tên khu trọ<input v-model="propertyName" placeholder="Ví dụ: Nhà trọ An Bình" maxlength="100" /></label><label>Địa chỉ<input v-model="address" placeholder="Số nhà, đường, phường/xã, tỉnh/thành" maxlength="250" /></label><div class="form-grid"><label>Người liên hệ<input v-model="contact" placeholder="Tên chủ trọ" maxlength="100" /></label><label>Điện thoại liên hệ<input v-model="contactPhone" type="tel" placeholder="0901234567" maxlength="15" /></label></div><p v-if="error" class="error" role="alert">{{ error }}</p><div class="actions"><button type="button" class="secondary" @click="emit('go', 'start')">Quay lại</button><button class="primary">Tạo khu trọ mẫu →</button></div></form></section><aside class="guide"><p class="eyebrow">SAU KHI TẠO</p><h2>Bạn là chủ khu trọ này.</h2><p>Quản lý phòng, duyệt người tham gia và theo dõi thu chi tại một nơi.</p><ul><li>Thêm phòng và thông tin cho thuê.</li><li>Gửi mã mời cho người thuê.</li><li>Duyệt tham gia, sau đó xác nhận nhận phòng.</li></ul><p class="fine">Mẫu này minh họa một khu. Phân quyền nhiều khu thật sẽ được triển khai ở đợt 3.</p></aside></div>
    </template>

    <template v-else-if="screen === 'invite'">
      <div class="heading"><p class="eyebrow">{{ demo.property.name }}</p><h1>Mời người thuê vào khu trọ</h1><p>Chia sẻ mã. Người nhận vẫn cần bạn duyệt trước khi vào khu.</p></div><div class="two-columns"><section class="card invite-card"><span class="pill" :class="{ warn: !demo.inviteActive }">{{ demo.inviteActive ? 'Mã mẫu đang hoạt động' : 'Mã đã thu hồi' }}</span><p>Mã tham gia khu trọ</p><div class="invite-code">{{ demo.invite }}</div><p class="sub">Minh họa hạn dùng 7 ngày · có thể dùng cho nhiều người</p><div class="actions"><button class="primary" :disabled="!demo.inviteActive" @click="copyCode">Sao chép mã</button><button class="secondary" @click="demo.inviteActive = !demo.inviteActive">{{ demo.inviteActive ? 'Thu hồi mã mẫu' : 'Bật lại mã mẫu' }}</button></div><button class="text-button" @click="emit('go', 'join')">Thử nhập mã với vai người thuê →</button></section><aside class="guide"><h2>Chủ trọ luôn có quyền duyệt.</h2><p>Biết mã chỉ giúp gửi yêu cầu. Người đang chờ không được xem dữ liệu riêng của khu.</p><button class="secondary" @click="emit('go', 'approvals')">Xem yêu cầu tham gia ({{ pending }})</button><p class="fine">Thu hồi mã chặn việc gửi mới. Hạn dùng và giới hạn mã chỉ là mô phỏng ở đợt này.</p></aside></div>
    </template>

    <template v-else-if="screen === 'join'">
      <div class="narrow"><div class="heading"><p class="eyebrow">KẾT NỐI VỚI CHỦ TRỌ</p><h1>Nhập mã khu trọ</h1><p>Mã được chủ trọ gửi cho bạn. Nhập mã để tìm đúng khu trước khi gửi yêu cầu.</p></div><section class="card"><form @submit.prevent="checkCode"><label>Mã tham gia<input v-model="code" class="code-input" placeholder="Ví dụ: ANBINH26" maxlength="24" @input="matched = false; error = ''" /></label><p class="hint">Để thử: nhập <button type="button" class="text-button" @click="code = demo.invite">{{ demo.invite }}</button></p><p v-if="error" class="error" role="alert">{{ error }}</p><button class="primary full">Kiểm tra mã</button></form><div v-if="matched" class="match"><span class="pill">Đã tìm thấy khu trọ</span><h2>{{ demo.property.name }}</h2><p>{{ demo.property.address }}</p><p>Chủ trọ: {{ demo.property.contact }}</p><p class="fine">Yêu cầu được gửi với hồ sơ mẫu {{ demo.name }}. Đây chưa phải xác nhận thuê phòng.</p><button class="primary full" @click="submitJoin">{{ mine && ['pending', 'approved'].includes(mine.status) ? 'Xem yêu cầu đã gửi' : 'Gửi yêu cầu tham gia' }}</button></div></section><button class="text-button" @click="emit('go', 'find')">Chưa có mã? Xem phòng đang đăng →</button></div>
    </template>

    <template v-else-if="screen === 'status'">
      <div class="narrow"><div class="heading"><p class="eyebrow">KHÔNG GIAN CỦA BẠN</p><h1>Khu trọ của tôi</h1><p>Theo dõi yêu cầu và bước tiếp theo tại đây.</p></div><section v-if="demo.rentalRequests.length" class="card application-list"><h2>Yêu cầu thuê của bạn</h2><article v-for="application in demo.rentalRequests" :key="application.room"><h3>Phòng {{ application.room }}</h3><span class="pill warn">Chờ chủ trọ liên hệ · mẫu</span><p>{{ application.people }} người · Ngày dự kiến {{ application.date }}</p><p class="fine">Gửi yêu cầu chưa giữ phòng hoặc cấp quyền vào khu.</p></article></section><section class="card status-card"><span class="status-symbol">{{ mine?.status === 'approved' ? '✓' : '…' }}</span><h2>{{ !mine ? 'Bạn chưa gửi yêu cầu' : mine.status === 'pending' ? 'Đang chờ chủ trọ duyệt' : mine.status === 'approved' ? 'Chào mừng vào khu trọ' : mine.status === 'rejected' ? 'Yêu cầu chưa được chấp thuận' : 'Bạn đã rút yêu cầu' }}</h2><p v-if="mine">{{ demo.property.name }}</p><template v-if="mine?.status === 'pending'"><p>Chủ trọ sẽ kiểm tra thông tin của bạn. Bạn chưa được truy cập dữ liệu riêng của khu trong lúc chờ.</p><ol class="progress"><li class="complete">Đã gửi yêu cầu</li><li class="active">Chờ duyệt</li><li>Vào khu trọ</li></ol><button class="secondary" @click="mine.status = 'withdrawn'">Rút yêu cầu</button></template><template v-else-if="mine?.status === 'approved'"><span class="pill">Thành viên đã được duyệt</span><div class="match"><h3>{{ mine.room ? `Phòng ${mine.room}` : 'Bạn chưa có phòng thuê' }}</h3><p>{{ mine.room ? 'Đã xác nhận nhận phòng trong dữ liệu mẫu. Hóa đơn thật chỉ xuất hiện khi chủ trọ lập cho đợt thuê của bạn.' : 'Liên hệ chủ trọ để xác nhận phòng hoặc liên kết hồ sơ thuê có sẵn. Chưa có quyền xem hóa đơn của người khác.' }}</p><p>Liên hệ: {{ demo.property.contact }} · {{ demo.property.phone }}</p></div><button class="secondary" @click="emit('go', 'find')">Xem các phòng đang đăng</button></template><template v-else><p v-if="mine?.reason">Lý do: {{ mine.reason }}</p><p>Kiểm tra thông tin với chủ trọ rồi gửi lại khi phù hợp.</p><button class="primary" @click="emit('go', 'join')">Nhập mã khu trọ</button></template></section><div class="demo-switch"><p>Thử luồng hai vai trò trong cùng bản mẫu:</p><button class="text-button" @click="emit('go', 'approvals')">Chuyển sang chủ trọ để duyệt →</button></div></div>
    </template>

    <template v-else-if="screen === 'approvals'">
      <div class="heading row"><div><p class="eyebrow">TIẾP NHẬN THÀNH VIÊN</p><h1>Yêu cầu tham gia</h1><p>{{ pending }} yêu cầu đang chờ · {{ demo.property.name }}</p></div><button class="secondary" @click="emit('go', 'invite')">Mã mời khu trọ</button></div><div class="info">Duyệt cho phép vào khu trọ. Xác nhận nhận phòng là một bước riêng sau khi đã kiểm tra người thuê.</div><section class="card request-panel"><div class="section-head"><h2>Danh sách yêu cầu</h2><label class="compact-label">Trạng thái<select v-model="requestFilter"><option value="pending">Chờ duyệt</option><option value="approved">Đã duyệt</option><option value="rejected">Từ chối</option><option value="">Tất cả</option></select></label></div><div v-if="!requests.length" class="empty"><h3>Không có yêu cầu ở trạng thái này</h3><p>Đổi bộ lọc hoặc thử nhập mã với vai người thuê.</p></div><article v-for="request in requests" :key="request.id" class="request-row"><div class="person-avatar">{{ request.name.split(' ').at(-1)?.slice(0,1) }}</div><div class="request-person"><h3>{{ request.name }} <small v-if="request.mine">Bạn đang mô phỏng</small></h3><p>{{ request.phone }} · Qua mã mời</p><p v-if="request.reason" class="fine">{{ request.reason }}</p></div><span class="pill" :class="{ warn: request.status === 'pending' }">{{ statusText(request.status) }}</span><div class="actions"><template v-if="request.status === 'pending'"><button class="primary" @click="decide(request, 'approve')">Duyệt</button><button class="secondary" @click="decide(request, 'reject')">Từ chối</button></template><template v-else-if="request.status === 'approved'"><span v-if="request.room" class="pill">Phòng {{ request.room }}</span><button v-else class="secondary" @click="decide(request, 'receive')">Xác nhận nhận phòng</button></template></div></article></section><button class="text-button" @click="emit('go', 'status')">Xem kết quả bên người thuê →</button>
    </template>

    <template v-else-if="screen === 'overview'">
      <div class="heading row"><div><p class="eyebrow">{{ demo.property.name }}</p><h1>Mọi việc trong tầm nhìn.</h1><p>Tình hình hiện tại và kết quả từng tháng, tách biệt rõ ràng.</p></div><button class="secondary" @click="emit('go', 'approvals')">Yêu cầu chờ duyệt <b class="number">{{ pending }}</b></button></div><section><div class="section-head"><h2>Nhà trọ lúc này</h2><span class="sub">Dữ liệu mẫu trong phiên xem</span></div><div class="stat-grid"><div class="stat"><span>Tổng phòng</span><strong>{{ rooms.length }}</strong><button class="text-button" @click="emit('go', 'rooms')">Xem danh sách →</button></div><div class="stat"><span>Phòng trống có thể thuê</span><strong>{{ rooms.filter(r => r.state === 'Còn trống' && !r.pending).length }}</strong><small>Không gồm bảo trì / chờ xóa</small></div><div class="stat"><span>Người đang ở</span><strong>{{ totalPeople }}</strong><small>Không đếm thành viên chờ duyệt</small></div><div class="stat"><span>Phòng bảo trì</span><strong>{{ rooms.filter(r => r.state === 'Bảo trì').length }}</strong><small>Tạm ngừng nhận người thuê</small></div></div></section><section class="monthly"><div class="section-head"><div><p class="eyebrow">KẾT QUẢ THEO KỲ</p><h2>Tổng kết tháng</h2></div><label class="compact-label">Tháng báo cáo<select v-model="month"><option value="2026-11">Tháng 11/2026</option><option value="2026-10">Tháng 10/2026</option></select></label></div><p class="sub">Số liệu cuối kỳ minh họa. Không thay đổi theo các thao tác thử phòng hiện tại.</p><div class="report-grid"><section class="financial"><p>Thực thu trong tháng</p><strong>{{ money(monthly.income) }}</strong><dl><div><dt>Thực chi</dt><dd>{{ money(monthly.expense) }}</dd></div><div><dt>Chênh lệch thu chi</dt><dd>{{ money(monthly.income - monthly.expense) }}</dd></div></dl><p class="fine">Tháng nhận tiền khác với kỳ lập hóa đơn.</p></section><section class="card"><h3>Cư trú trong tháng</h3><div class="residence-stats"><div><strong>{{ monthly.entered }}</strong><span>Người vào</span></div><div><strong>{{ monthly.left }}</strong><span>Người rời</span></div><div><strong>{{ monthly.people }}</strong><span>Ở cuối tháng</span></div></div><p class="sub">{{ monthly.vacant }} phòng trống tại cuối tháng đã chọn.</p><h3>Thu tiền hóa đơn kỳ {{ month }}</h3><div class="bar" aria-label="Đã thu và còn phải thu"><span :style="{ width: `${monthly.income / monthly.total * 100}%` }"></span></div><p class="legend">Đã thu {{ money(monthly.income) }} · Còn {{ money(monthly.total - monthly.income) }}</p></section></div></section><section class="card"><div class="section-head"><h2>Người ở theo phòng · hiện tại</h2><span class="sub">Sức chứa không phải số người thực ở</span></div><div class="room-summary"><article v-for="room in rooms" :key="room.name"><strong>{{ room.name }}</strong><span>{{ room.residents }} / {{ room.capacity }} người</span><span class="pill" :class="{ warn: room.pending || room.state === 'Bảo trì' }">{{ room.pending ? 'Chờ xóa' : room.state }}</span></article></div></section>
    </template>

    <UiDialog :open="!!action" :title="action === 'approve' ? 'Duyệt tham gia khu trọ' : action === 'reject' ? 'Từ chối yêu cầu' : 'Xác nhận nhận phòng mẫu'" @update:open="value => { if (!value) action = '' }"><div class="decision"><p><strong>{{ selected?.name }}</strong> · {{ selected?.phone }}</p><p v-if="action === 'approve'">Người này được vào khu trọ sau khi duyệt. Chưa được tự động xem hóa đơn hoặc dữ liệu thuê của phòng nào.</p><label v-else-if="action === 'reject'">Lý do từ chối<textarea v-model="reason" rows="3" maxlength="250" placeholder="Ví dụ: cần kiểm tra lại thông tin với chủ trọ" /></label><template v-else><p>Chỉ thực hiện sau khi đã xác nhận việc thuê với người này. Bản mẫu nhận một người vào phòng trống.</p><label>Phòng còn trống<select v-model="roomName"><option value="">Chọn phòng</option><option v-for="room in rooms.filter(r => r.state === 'Còn trống' && !r.pending)" :key="room.name" :value="room.name">{{ room.name }} · tối đa {{ room.capacity }} người</option></select></label></template><p v-if="error" class="error" role="alert">{{ error }}</p></div><template #actions><button class="secondary" @click="action = ''">Quay lại</button><button class="primary" @click="confirm">{{ action === 'approve' ? 'Xác nhận duyệt' : action === 'reject' ? 'Xác nhận từ chối' : 'Xác nhận nhận phòng' }}</button></template></UiDialog>
  </div>
</template>

